+  return Buffer.from(JSON.stringify({off: offset}), 'utf8').toString('base64url');
+}
+
+function decodeCursor(cursor) {
+  if (typeof cursor !== 'string' || cursor.length === 0) {
+    throw new Error('Unknown cursor');
+  }
+  let obj;
+  try {
+    obj = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
+  } catch {
+    throw new Error('Unknown cursor');
+  }
+  if (!obj || typeof obj !== 'object' ||
+      !Number.isInteger(obj.off) ||
+      obj.off < 0 || obj.off >= events.length) {
+    throw new Error('Unknown cursor');
+  }
+  // Reject non-canonical / tampered cursors by requiring a stable round-trip.
+  if (encodeCursor(obj.off) !== cursor) {
+    throw new Error('Unknown cursor');
+  }
+  return obj.off;
+}
+
+export async function listTools() {
+  return [{
+    name: 'events_list',
+    description: 'List events in source order with optional cursor pagination.',
+    inputSchema: {
+      type: 'object',
+      properties: {
+        cursor: {
+          type: 'string',
+          description: 'Opaque pagination cursor returned by a previous events_list response. Omit to start from the first event.'
+        },
+        page_size: {
+          type: 'integer',
+          minimum: 1,
+          maximum: 3,
+          description: 'Number of events to return per page. Must be an integer from 1 to 3. Defaults to 2.'
+        }
+      },
+      required: [],
+      additionalProperties: false
+    }
+  }];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'events_list') {
+    throw new Error('Unknown tool: ' + name);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error('Unexpected field: ' + key);
+    }
+  }
+
+  let offset = 0;
+  if (args.cursor !== undefined) {
+    offset = decodeCursor(args.cursor);
+  }
+
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if (args.page_size !== undefined) {
+    const ps = args.page_size;
+    if (!Number.isInteger(ps) || ps < 1 || ps > 3) {
+      throw new Error('page_size must be an integer from 1 to 3');
+    }
+    pageSize = ps;
+  }
+
+  const page = events.slice(offset, offset + pageSize);
+  const nextOffset = offset + pageSize;
+
+  const result = {events: page};
+  if (nextOffset < events.length) {
+    result.next_cursor = encodeCursor(nextOffset);
+  }
+
+  return {content: [{type: 'text', text: JSON.stringify(result)}]};
+}
